using UnityEngine;

namespace SimuLean.Unity
{
    /// <summary>
    /// Marks a GameObject as generated by a <see cref="UnityStorageRack"/>
    /// rebuild, so a later rebuild deletes only its own output and never
    /// touches user-authored children. Also records the logical indices for
    /// debugging / future tooling.
    /// </summary>
    public class UnityStorageSlotMarker : MonoBehaviour
    {
        public int bay;
        public int slot;
        public int level;
    }
}
